/*
 * Chart series palette, derived from uikit private color tokens.
 * Each theme gets its own ramp steps (not an automatic flip): the light and dark
 * sets were both validated for lightness band, chroma, CVD separation and contrast
 * against their respective surfaces (--g-color-base-background).
 *
 * Must be imported AFTER @gravity-ui/uikit/styles/styles.css.
 */
.g-root {
  --app-chart-series-1: var(--g-color-private-blue-600-solid);
  --app-chart-series-2: var(--g-color-private-orange-600-solid);
  --app-chart-series-3: var(--g-color-private-purple-600-solid);
}

.g-root_theme_dark,
.g-root_theme_dark-hc {
  --app-chart-series-1: var(--g-color-private-blue-550-solid);
  --app-chart-series-2: var(--g-color-private-orange-550-solid);
  --app-chart-series-3: var(--g-color-private-purple-550-solid);
}

/* Axis/grid lines and data labels are already bound to --g-* tokens by @gravity-ui/charts;
   keep the brush/selection consistent with the brand token instead of the hardcoded default. */
.app-chart {
  --gcharts-brush-border-color: var(--g-color-line-generic-accent);
}

